"use client";

/**
 * Button dive: the button is pressed, the camera pushes into it until its fill
 * covers the frame, and the fill opens into the app it leads to.
 *
 * Written by Better Design. Painted from the theme prop; with no screenshot the
 * app surface is a placeholder dashboard drawn from the same tokens.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, random, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const PRESS_AT = 12;
const PUSH_FROM = 22;
const PUSH_TO = 58;
const OPEN_TO = 96;
/** How far the camera zooms. Enough for the button to cover the frame. */
const MAX_ZOOM = 32;
/** Button centre, in frame pixels. The zoom is anchored here. */
const CX = 960;
const CY = 640;

export interface ButtonDiveProps {
  /** The text on the button. */
  label?: string;
  /** One line above the button. */
  headline?: string;
  /** Image URL or static file for the app surface. Drawn as a placeholder when absent. */
  screenshot?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

function PlaceholderSurface({ theme }: { theme: VideoTheme }) {
  const bar = (w: number | string, h: number, c = withAlpha(theme.foreground, 0.12)) => (
    <div style={{ width: w, height: h, borderRadius: h / 2, background: c }} />
  );
  return (
    <div style={{ position: "absolute", inset: 0, display: "flex", background: theme.background }}>
      <div style={{ width: 300, padding: "48px 28px", display: "flex", flexDirection: "column", gap: 22, background: theme.card, borderRight: `1px solid ${theme.border}` }}>
        <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 20 }}>
          <div style={{ width: 40, height: 40, borderRadius: 12, background: theme.primary }} />
          {bar(110, 16, withAlpha(theme.foreground, 0.8))}
        </div>
        {[150, 120, 170, 100, 140].map((w, i) => (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 14, padding: "12px 14px", borderRadius: 12, background: i === 0 ? withAlpha(theme.primary, 0.12) : "transparent" }}>
            <div style={{ width: 22, height: 22, borderRadius: 7, background: i === 0 ? theme.primary : withAlpha(theme.foreground, 0.18) }} />
            {bar(w, 12, i === 0 ? withAlpha(theme.primary, 0.7) : undefined)}
          </div>
        ))}
      </div>
      <div style={{ flex: 1, padding: "48px 56px", display: "flex", flexDirection: "column", gap: 32 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          {bar(340, 26, withAlpha(theme.foreground, 0.85))}
          <div style={{ width: 170, height: 52, borderRadius: 26, background: theme.primary }} />
        </div>
        <div style={{ display: "flex", gap: 28 }}>
          {[0.6, 0.45, 0.7].map((w, i) => (
            <div key={i} style={{ flex: 1, height: 170, padding: 28, borderRadius: theme.radius * 2, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
              {bar(`${w * 100}%`, 12)}
              {bar(`${w * 70}%`, 34, withAlpha(theme.foreground, 0.75))}
            </div>
          ))}
        </div>
        <div style={{ flex: 1, padding: 36, borderRadius: theme.radius * 2, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", alignItems: "flex-end", gap: 22 }}>
          {Array.from({ length: 14 }, (_, i) => (
            <div key={i} style={{ flex: 1, height: `${30 + random(`dive-${i}`) * 65}%`, borderRadius: 10, background: i === 10 ? theme.primary : withAlpha(theme.primary, 0.22) }} />
          ))}
        </div>
      </div>
    </div>
  );
}

/** Push into a primary button until its fill becomes the app it opens. */
export function ButtonDive({
  label = "Get started",
  headline = "One click away.",
  screenshot,
  theme: themeOverride,
  font,
}: ButtonDiveProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const enter = easings.out(interpolate(frame, [0, 16], [0, 1], clamp));
  const press = interpolate(frame, [PRESS_AT, PRESS_AT + 4, PRESS_AT + 10], [1, 0.94, 1], clamp);
  // Zoom on a log scale so the push reads as one steady camera move.
  const push = easings.inOut(interpolate(frame, [PUSH_FROM, PUSH_TO], [0, 1], clamp));
  const zoom = Math.exp(Math.log(MAX_ZOOM) * push);
  const labelFade = interpolate(zoom, [1, 2.4], [1, 0], clamp);

  const open = easings.out(interpolate(frame, [PUSH_TO - 4, OPEN_TO], [0, 1], clamp));
  const scale = interpolate(open, [0, 1], [0.38, 1]);
  const radius = interpolate(open, [0, 1], [56, 0]) / scale;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill style={{ transformOrigin: `${CX}px ${CY}px`, transform: `scale(${zoom})` }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 360, textAlign: "center", fontSize: 92, fontWeight: 700, letterSpacing: "-0.035em", color: theme.foreground, opacity: enter * labelFade, transform: `translateY(${(1 - enter) * 20}px)` }}>
          {headline}
        </div>
        <div
          style={{
            position: "absolute",
            left: CX - 200,
            top: CY - 56,
            width: 400,
            height: 112,
            borderRadius: 56,
            background: theme.primary,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: `0 18px 40px -16px ${withAlpha(theme.primary, 0.6 * labelFade)}`,
            opacity: enter,
            transform: `scale(${press * (0.94 + 0.06 * enter)})`,
          }}
        >
          <span style={{ fontSize: 40, fontWeight: 600, color: theme.primaryForeground, opacity: labelFade }}>{label}</span>
        </div>
      </AbsoluteFill>

      {open > 0 && (
        <AbsoluteFill style={{ background: theme.primary }}>
          <div
            style={{
              position: "absolute",
              inset: 0,
              overflow: "hidden",
              borderRadius: radius,
              opacity: interpolate(open, [0, 0.15], [0, 1], clamp),
              transform: `translateY(${(1 - open) * 40}px) scale(${scale})`,
              boxShadow: "0 40px 120px -30px oklch(0 0 0 / 0.45)",
            }}
          >
            {screenshot ? <Img src={srcOf(screenshot)} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <PlaceholderSurface theme={theme} />}
          </div>
        </AbsoluteFill>
      )}
    </AbsoluteFill>
  );
}
